use std::fs

fn digit(c: char) -> int {
    if c >= '0' && c <= '9' {
        c as int - '0' as int
    } else {
        -1
    }
}

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

// returns days since 1970-01-01, or -1000000 when invalid
fn parse_date(s: string) -> int {
    let cs: Vec<char> = s.chars().collect()
    if cs.len() != 10 {
        return -1000000
    }
    if cs[4] != '-' || cs[7] != '-' {
        return -1000000
    }
    let mut vals: Vec<int> = []
    let idx = [0, 1, 2, 3, 5, 6, 8, 9]
    for i in idx {
        let d = digit(cs[i])
        if d < 0 {
            return -1000000
        }
        vals.push(d)
    }
    let y = vals[0] * 1000 + vals[1] * 100 + vals[2] * 10 + vals[3]
    let m = vals[4] * 10 + vals[5]
    let d = vals[6] * 10 + vals[7]
    if m < 1 || m > 12 || d < 1 || d > days_in(y, m) {
        return -1000000
    }
    let yy = if m <= 2 { y - 1 } else { y }
    let era = yy / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn main() {
    let names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let parts: Vec<string> = t.split_whitespace().collect()
        if parts.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(parts[0])
        let b = parse_date(parts[1])
        if a == -1000000 || b == -1000000 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let w = ((lo + 3) % 7 + 7) % 7
        println("${diff} ${names[w as usize]}")
    }
}

